package com.opensocket.aievent.core.iam.authentication.domain;
import java.time.Duration;
public record SessionPolicy(Duration idleTimeout,Duration absoluteTimeout,int maxConcurrentSessions,boolean revokeOnPasswordChange,boolean revokeOnMfaReset,Duration reauthenticationWindow){public SessionPolicy{idleTimeout=idleTimeout==null?Duration.ofMinutes(30):idleTimeout;absoluteTimeout=absoluteTimeout==null?Duration.ofHours(12):absoluteTimeout;if(idleTimeout.isNegative()||idleTimeout.isZero()||absoluteTimeout.compareTo(idleTimeout)<=0)throw new IllegalArgumentException("session timeout policy is invalid");if(maxConcurrentSessions<1||maxConcurrentSessions>100)throw new IllegalArgumentException("maxConcurrentSessions must be 1..100");reauthenticationWindow=reauthenticationWindow==null?Duration.ofMinutes(5):reauthenticationWindow;if(reauthenticationWindow.isNegative()||reauthenticationWindow.isZero())throw new IllegalArgumentException("reauthenticationWindow must be positive");}public static SessionPolicy secureDefault(){return new SessionPolicy(Duration.ofMinutes(30),Duration.ofHours(12),5,true,true,Duration.ofMinutes(5));}public static SessionPolicy rootRecovery(){return new SessionPolicy(Duration.ofMinutes(5),Duration.ofMinutes(30),1,true,true,Duration.ofMinutes(2));}
public static SessionPolicy passwordChangeRequired(Duration absoluteTimeout){Duration ttl=absoluteTimeout==null?Duration.ofMinutes(10):absoluteTimeout;if(ttl.compareTo(Duration.ofMinutes(1))<0||ttl.compareTo(Duration.ofMinutes(30))>0)throw new IllegalArgumentException("password-change session TTL must be between 1 and 30 minutes");Duration idle=ttl.compareTo(Duration.ofMinutes(5))>0?Duration.ofMinutes(5):ttl.dividedBy(2);return new SessionPolicy(idle,ttl,1,true,true,Duration.ofMinutes(1));}}
